package com.hbm.machine.solarboiler;
import java.util.*;import net.minecraft.core.registries.Registries;import net.minecraft.world.item.*;import net.minecraft.world.level.block.entity.BlockEntityType;import net.neoforged.bus.api.IEventBus;import net.neoforged.neoforge.registries.*;
public final class SolarBoilerContent {
 private static final DeferredRegister.Blocks BLOCKS=DeferredRegister.createBlocks("hbm");private static final DeferredRegister.Items ITEMS=DeferredRegister.createItems("hbm");private static final DeferredRegister<BlockEntityType<?>> BE=DeferredRegister.create(Registries.BLOCK_ENTITY_TYPE,"hbm");
 public static final DeferredBlock<SteelBeamBlock> BEAM=BLOCKS.register("steel_beam",SteelBeamBlock::new);public static final DeferredItem<BlockItem> BEAM_ITEM=ITEMS.registerSimpleBlockItem(BEAM);
 public static final DeferredBlock<SolarBoilerBlock> BOILER=BLOCKS.register("machine_solar_boiler",SolarBoilerBlock::new);public static final DeferredBlock<SolarMirrorBlock> MIRROR=BLOCKS.register("solar_mirror",SolarMirrorBlock::new);public static final DeferredItem<BlockItem> BOILER_ITEM=ITEMS.registerSimpleBlockItem(BOILER),MIRROR_ITEM=ITEMS.registerSimpleBlockItem(MIRROR);public static final DeferredItem<MirrorToolItem> TOOL=ITEMS.register("mirror_tool",MirrorToolItem::new);
 public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<SolarBoilerBlockEntity>> BOILER_BE=BE.register("machine_solar_boiler",()->BlockEntityType.Builder.of(SolarBoilerBlockEntity::new,BOILER.get()).build(null));public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<SolarBoilerProxy>> PROXY_BE=BE.register("solar_boiler_proxy",()->BlockEntityType.Builder.of(SolarBoilerProxy::new,BOILER.get()).build(null));public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<SolarMirrorBlockEntity>> MIRROR_BE=BE.register("solar_mirror",()->BlockEntityType.Builder.of(SolarMirrorBlockEntity::new,MIRROR.get()).build(null));
 public static void register(IEventBus bus){BLOCKS.register(bus);ITEMS.register(bus);BE.register(bus);}
 public static List<ItemStack> creativeStacks(String tab){return tab.equals("machine")?List.of(new ItemStack(BOILER_ITEM.get()),new ItemStack(MIRROR_ITEM.get())):tab.equals("block")?List.of(new ItemStack(BEAM_ITEM.get())):tab.equals("consumable")?List.of(new ItemStack(TOOL.get())):List.of();}
 public static List<ItemStack> allStacks(){return List.of(new ItemStack(BOILER_ITEM.get()),new ItemStack(MIRROR_ITEM.get()),new ItemStack(TOOL.get()),new ItemStack(BEAM_ITEM.get()));}
 private SolarBoilerContent(){}
}
